using System;using System.IO;using System.Drawing;using System.Windows.Forms;
internal static partial class SmartPalette{
 internal static SmartColors UiRecipe(string source,int mode){var p=Generate(source,0,mode);var seed=ToOk(ColorTranslator.FromHtml(p.Seed));double hue=seed.Hue,c=seed.C<.02?0:1;string[] values;
  if(mode==0){values=new[]{Hex(Tone(hue,.006*c,.96)),Hex(Tone(hue,.008*c,.975)),Hex(Tone(hue,.004*c,.985)),Hex(Tone(hue,.009*c,.945)),Hex(Tone(hue,.007*c,.95)),Hex(Tone(hue,.028*c,.88)),Hex(Tone(hue,.019*c,.935)),Hex(Tone(hue,.004*c,.982))};p.Text=Hex(Tone(hue,.005*c,.23));p.Icons=Hex(Tone(hue,.009*c,.34));p.Accent=Hex(Tone(hue-12,.1*c,.46));p.Border=Hex(Tone(hue,.008*c,.64));p.Effects=new EffectSettings{Brightness=100,Color=Hex(Tone(hue,.006*c,.97)),Friends=74,Header=78,Navigation=78,Input=45};p.InputOpacity=38;}
  else{values=new[]{Hex(Tone(hue,.008*c,.18)),Hex(Tone(hue,.011*c,.22)),Hex(Tone(hue,.006*c,.15)),Hex(Tone(hue,.012*c,.255)),Hex(Tone(hue,.01*c,.19)),Hex(Tone(hue-6,.036*c,.36)),Hex(Tone(hue,.026*c,.315)),Hex(Tone(hue,.009*c,.255))};p.Text=Hex(Tone(hue,.006*c,.97));p.Icons=Hex(Tone(hue,.009*c,.88));p.Accent=Hex(Tone(hue-12,.08*c,.8));p.Border=Hex(Tone(hue,.009*c,.58));p.Effects=new EffectSettings{Brightness=100,Color=Hex(Tone(hue,.008*c,.18)),Friends=76,Header=78,Navigation=78,Input=45};p.InputOpacity=38;}
  if(mode==0){ApplyLightHierarchy(p,new PaletteAssignment{Primary=p.Seed,Secondary=p.Seed,Neutral=p.Seed,Accent=p.Seed});TuneUiContrast(source,p,new PaletteAssignment{Primary=p.Seed});return p;}p.Theme=Palette.Make("壁纸统一界面",values,values);return p;}
 internal static string SecondaryFor(SmartColors p){if(p.SecondaryText!=null)return p.SecondaryText;var seed=ToOk(ColorTranslator.FromHtml(p.Seed));return Hex(Tone(seed.Hue,seed.C<.02?0:.006,p.RuntimeMode==0?.36:.87));}
}
internal static class VisualStyle{
 public static string BackupPath{get{return Path.Combine(Engine.Store,"visual-style-before.wxtheme");}}
 public static void Apply(){string source=AutoBackground.SavedImage();if(source==null)throw new IOException("请先选择壁纸。");if(Engine.Hash(File.ReadAllBytes(Engine.Target))!=Engine.OriginalHash)throw new IOException("请先退出微信并应用登录页保护升级，再使用统一界面风格。");AppearanceProfiles.EnsureProfiles();var theme=Engine.Current();ThemeTransfer.Export(BackupPath,theme,Engine.Store);for(int mode=0;mode<2;mode++){var p=SmartPalette.UiRecipe(source,mode);for(int i=0;i<8;i++)theme.Colors[i*2+mode]=p.Theme.Colors[i*2+mode];SmartPalette.Commit(p);using(AppearanceProfiles.Use(mode)){NativeBackground.InkSecondary=SmartPalette.SecondaryFor(p);NativeBackground.InkCanvas="auto";var inputBorder=InputAppearance.Load();inputBorder.Edge=44;inputBorder.Radius=10;InputAppearance.Save(inputBorder);}}theme.Name="壁纸统一界面";Engine.SaveRuntimeTheme(theme);AutoBackground.SetEnabled(true);}
 public static void ApplyLight(){AppearanceProfiles.EnsureProfiles();var source=AutoBackground.SavedImage();if(source==null)throw new IOException("请先选择壁纸。");var theme=Engine.Current();ThemeTransfer.Export(Path.Combine(Engine.Store,"light-design-before.wxtheme"),theme,Engine.Store);var p=SmartPalette.UiRecipe(source,0);p.Effects=new EffectSettings{Brightness=100,Tint=58,Color="#F9F5F2",Friends=20,Header=20,Navigation=20,Input=0};for(int i=0;i<8;i++)theme.Colors[i*2]=p.Theme.Colors[i*2];SmartPalette.Commit(p);using(AppearanceProfiles.Use(0)){NativeBackground.InkText="#242120";NativeBackground.InkChat="#242120";NativeBackground.InkSecondary="#49413E";NativeBackground.InkCanvas="#242120";NativeBackground.InkIcons="#34302E";var inputBorder=InputAppearance.Load();inputBorder.Edge=45;inputBorder.BorderColor="#7B7069";InputAppearance.Save(inputBorder);}Engine.SaveRuntimeTheme(theme);AutoBackground.SetEnabled(true);}
 public static void Restore(){if(!File.Exists(BackupPath))throw new IOException("没有统一界面风格的备份。");var before=ThemeTransfer.Read(BackupPath);Engine.SaveRuntimeTheme(before.Theme);ThemeTransfer.Commit(before);}
}
internal sealed partial class Studio{
 void AddVisualStyleControls(Panel p){var unified=WorkspaceButton(p,"统一界面材质与层级",590,43,300);unified.Click+=delegate{try{VisualStyle.Apply();RefreshSmartForms();status.Text="已统一浅深两套材质与文字层级；壁纸原图保留，后台自动刷新。";}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};var undo=WorkspaceButton(workspacePages["recovery"],"撤销上次界面风格",500,430,240);undo.Click+=delegate{try{VisualStyle.Restore();RefreshSmartForms();status.Text="已恢复统一界面风格之前的配色和材质。";}catch(Exception e){AppLog.Error("UI",e);status.Text=e.Message;}};}
}
